(238243, 14942, 3280, '<td valign="top">Beautiful shot, the leading lines to the clock are great and I like the colors and framing.</td>', 'Beautiful shot, the leading lines to the clock are great and I like the colors and framing.', '2003-03-17 00:17:37.000000', NULL, 1),
(238245, 14909, 3280, '<td valign="top">Nice job of lighting and negative space.  I really like this a lot.</td>', 'Nice job of lighting and negative space.  I really like this a lot.', '2003-03-17 00:19:02.000000', NULL, 1),
