INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(239789, 14726, 6328, '<td valign="top">Well, you almost got everything you''d need, haven''t you?<br/>good colour, good lighting, very original idea, nice job.</td>', 'Well, you almost got everything you''d need, haven''t you?good colour, good lighting, very original idea, nice job.', '2003-03-18 01:39:16.000000', NULL, 1),
(239793, 14946, 6328, '<td valign="top">Good job on this shot.<br/>Lots of colour in this picture, good content, meets thechallenge that''s for sure.<br/></td>', 'Good job on this shot.Lots of colour in this picture, good content, meets thechallenge that''s for sure.', '2003-03-18 01:40:57.000000', NULL, 1),
(239794, 14933, 6328, '<td valign="top">Lovely colours here, nice lighting, nice shadow content.<br/>focus is good, great idea for this shot.</td>', 'Lovely colours here, nice lighting, nice shadow content.focus is good, great idea for this shot.', '2003-03-18 01:41:59.000000', NULL, 1),
(239795, 14919, 6892, '<td valign="top">Lovely rose, but there is no reference point to indicate whether this photo was taken from above or from the sides. The color is gorgeous.</td>', 'Lovely rose, but there is no reference point to indicate whether this photo was taken from above or from the sides. The color is gorgeous.', '2003-03-18 01:42:59.000000', NULL, 1),
(239797, 14516, 6328, '<td valign="top">Nice black and white shot of the tattoo''s.  Very original idea.  Nice sharp focus.<br/>Great visual impact.  Perhaps just a bit too tight on the cropping, maybe should show the whole tattoo''s?<br/>Great shot though.</td>', 'Nice black and white shot of the tattoo''s.  Very original idea.  Nice sharp focus.Great visual impact.  Perhaps just a bit too tight on the cropping, maybe should show the whole tattoo''s?Great shot though.', '2003-03-18 01:44:12.000000', NULL, 1),
(239798, 14864, 6892, '<td valign="top">Was this taken from the arch in St. Louis?</td>', 'Was this taken from the arch in St. Louis?', '2003-03-18 01:44:19.000000', NULL, 1),
(239801, 14743, 6892, '<td valign="top">Tranquill indeed. Where is this lovely place?</td>', 'Tranquill indeed. Where is this lovely place?', '2003-03-18 01:45:50.000000', NULL, 1),
(239803, 14794, 6892, '<td valign="top">The angle of the model''s eyes is the only giveaway that this was taken from above. Well done.</td>', 'The angle of the model''s eyes is the only giveaway that this was taken from above. Well done.', '2003-03-18 01:46:58.000000', NULL, 1),
(239804, 14285, 6328, '<td valign="top">Me thinks that what makes this a picture is what you''ve done with it.  <br/>I see some good focus, some not so bad lighting. . .<br/>And for that, I''ll give you a</td>', 'Me thinks that what makes this a picture is what you''ve done with it.  I see some good focus, some not so bad lighting. . .And for that, I''ll give you a', '2003-03-18 01:47:06.000000', NULL, 1),
(239805, 14038, 6328, '<td valign="top">Nice and bright, good lighting, mainly natural?<br/>good focus, nice and sharp.<br/>great idea for a photo.<br/>Meets the challenge, that''s for sure.</td>', 'Nice and bright, good lighting, mainly natural?good focus, nice and sharp.great idea for a photo.Meets the challenge, that''s for sure.', '2003-03-18 01:48:31.000000', NULL, 1),
