(239979, 14386, 6663, '<td valign="top">Great focus and lighting.</td>', 'Great focus and lighting.', '2003-03-18 07:59:22.000000', NULL, 1),
(239980, 14743, 6663, '<td valign="top">Superb colours and detail. Nice the way you caught the ripples.</td>', 'Superb colours and detail. Nice the way you caught the ripples.', '2003-03-18 08:00:45.000000', NULL, 1),
(239981, 14843, 2978, '<td valign="top">Aha! I see a stain in your steel. Good abstract (apart from the stain)</td>', 'Aha! I see a stain in your steel. Good abstract (apart from the stain)', '2003-03-18 08:02:56.000000', NULL, 1),
(239983, 14699, 2978, '<td valign="top">Get out of the box</td>', 'Get out of the box', '2003-03-18 08:04:27.000000', NULL, 1),
(239984, 14434, 6663, '<td valign="top">I really like this. Surreal effect, great idea to put someone at the bottom, really makes it look like a corridor. Where did you find a building with such a long flight of stairs? Great pic though 9.</td>', 'I really like this. Surreal effect, great idea to put someone at the bottom, really makes it look like a corridor. Where did you find a building with such a long flight of stairs? Great pic though 9.', '2003-03-18 08:05:12.000000', NULL, 1),
