(239986, 14895, 2978, '<td valign="top">Good motion capture.</td>', 'Good motion capture.', '2003-03-18 08:07:50.000000', NULL, 1),
(239987, 14714, 6663, '<td valign="top">Fantastic idea, great shot. It took me a little while to realise this wasn''t just a shot of a pair of gates but of the shadow they cast! Really crisp detail on the shadow. This deserves a very high place in my opinion 9.</td>', 'Fantastic idea, great shot. It took me a little while to realise this wasn''t just a shot of a pair of gates but of the shadow they cast! Really crisp detail on the shadow. This deserves a very high place in my opinion 9.', '2003-03-18 08:07:57.000000', NULL, 1),
(239988, 14721, 2978, '<td valign="top">I''m not lsure about the angle at all.</td>', 'I''m not lsure about the angle at all.', '2003-03-18 08:09:46.000000', NULL, 1),
(239989, 14689, 6663, '<td valign="top">Very effective shot but I''m pretty sure this wasn''t taken ''from above''...pity or I would have scored it higher. 7.</td>', 'Very effective shot but I''m pretty sure this wasn''t taken ''from above''...pity or I would have scored it higher. 7.', '2003-03-18 08:09:46.000000', NULL, 1),
(239990, 14385, 2978, '<td valign="top">Pretty</td>', 'Pretty', '2003-03-18 08:11:26.000000', NULL, 1),
(239992, 14152, 6663, '<td valign="top">Makes for a pretty spectacular shot from above...nice idea 7.</td>', 'Makes for a pretty spectacular shot from above...nice idea 7.', '2003-03-18 08:14:08.000000', NULL, 1),
(239995, 14597, 6663, '<td valign="top">Great expression on the little guy''s face but it''s a little out of focus. One of the better of this week''s obligatory smattering of ''animal/small child'' shots.</td>', 'Great expression on the little guy''s face but it''s a little out of focus. One of the better of this week''s obligatory smattering of ''animal/small child'' shots.', '2003-03-18 08:15:50.000000', NULL, 1),
(239996, 14677, 6663, '<td valign="top">Fantastic colour, must''ve taken a bit of elbow grease to get the car looking like that! I really like the surreal effect of the shadows on the bonnet. Very nice shot 8.</td>', 'Fantastic colour, must''ve taken a bit of elbow grease to get the car looking like that! I really like the surreal effect of the shadows on the bonnet. Very nice shot 8.', '2003-03-18 08:16:53.000000', NULL, 1),
(239997, 14772, 2978, '<td valign="top">I like this shot. it''s clever to compose the chair on the bottom left. Well done.</td>', 'I like this shot. it''s clever to compose the chair on the bottom left. Well done.', '2003-03-18 08:17:29.000000', NULL, 1),
(239998, 14451, 2978, '<td valign="top">Not enough above for me.</td>', 'Not enough above for me.', '2003-03-18 08:18:48.000000', NULL, 1),
(239999, 14909, 6663, '<td valign="top">Great idea for the shot - the cactus reminds me of a lone actor on stage. Good colours too but could have done with a little more crispness in the focus. 7.</td>', 'Great idea for the shot - the cactus reminds me of a lone actor on stage. Good colours too but could have done with a little more crispness in the focus. 7.', '2003-03-18 08:18:58.000000', NULL, 1),
