(240579, 14782, 2158, '<td valign="top">That background really doesn''t do the snake justice.</td>', 'That background really doesn''t do the snake justice.', '2003-03-18 16:24:41.000000', NULL, 1),
(240580, 14752, 6667, '<td valign="top">Enter your comment here, and then cast your vote...Did you try any other cropping for this shot?  Vertical may have been the way to shot this one.  Too much green distracts me from the neat falls and lake.</td>', 'Enter your comment here, and then cast your vote...Did you try any other cropping for this shot?  Vertical may have been the way to shot this one.  Too much green distracts me from the neat falls and lake.', '2003-03-18 16:26:47.000000', NULL, 1),
(240582, 14790, 2158, '<td valign="top">I love this.  I really wanted to do a staircase for this challenge, but I couldn''t find one worth taking a photo of.</td>', 'I love this.  I really wanted to do a staircase for this challenge, but I couldn''t find one worth taking a photo of.', '2003-03-18 16:28:03.000000', NULL, 1),
(240585, 14909, 2158, '<td valign="top">Nice job.  The negative space really makes this photo.</td>', 'Nice job.  The negative space really makes this photo.', '2003-03-18 16:33:42.000000', NULL, 1),
(240586, 14750, 772, '<td valign="top">She''s a hottie :)  I''ll ask for her phone number after the challenge ;)  - great composition and I really like the high key lighting.. great work :) - setzler</td>', 'She''s a hottie :)  I''ll ask for her phone number after the challenge ;)  - great composition and I really like the high key lighting.. great work :) - setzler', '2003-03-18 16:36:41.000000', NULL, 1),
(240587, 14418, 772, '<td valign="top">This is a really neat abstract photo and I really like the blue as well... It took me a little while to determine that I was looking at a corner pocket on a pool table... The abstract nature of this shot could make it difficult for people to determine the ''from above'' nature of it... excellent work though :) - setzler</td>', 'This is a really neat abstract photo and I really like the blue as well... It took me a little while to determine that I was looking at a corner pocket on a pool table... The abstract nature of this shot could make it difficult for people to determine the ''from above'' nature of it... excellent work though :) - setzler', '2003-03-18 16:38:01.000000', NULL, 1),
(240589, 14795, 772, '<td valign="top">This is a really nice landscape, but I would have cropped the tree that is hugging the left side of the frame... nice work :) - setzler</td>', 'This is a really nice landscape, but I would have cropped the tree that is hugging the left side of the frame... nice work :) - setzler', '2003-03-18 16:39:38.000000', NULL, 1),
