INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(241516, 14894, 4275, '<td valign="top">please do everything in your power to stop the dredid war</td>', 'please do everything in your power to stop the dredid war', '2003-03-19 14:41:37.000000', NULL, 1),
(241524, 14286, 6999, '<td valign="top">Beautiful colouration - and one of few macros that have kept a sense of looking down as well as the depth of field.</td>', 'Beautiful colouration - and one of few macros that have kept a sense of looking down as well as the depth of field.', '2003-03-19 14:59:12.000000', NULL, 1),
(241527, 14418, 6999, '<td valign="top">great abstract - I have no odea what this is. Doesn''t say ''down'' to me at all though.</td>', 'great abstract - I have no odea what this is. Doesn''t say ''down'' to me at all though.', '2003-03-19 15:03:29.000000', NULL, 1),
(241528, 14728, 6999, '<td valign="top">Excellent shot - the tones of those leaves caught in the water are wonderful. The composition desn''t seem quite right to me: not sure whether those leaves or the waterfall are the real subject - my eye is pulled both ways.</td>', 'Excellent shot - the tones of those leaves caught in the water are wonderful. The composition desn''t seem quite right to me: not sure whether those leaves or the waterfall are the real subject - my eye is pulled both ways.', '2003-03-19 15:06:08.000000', NULL, 1),
(241533, 14750, 6913, '<td valign="top">Impressive photograph, but you should have tried to frame your model at an angle to improve a composition and reduce the ambiguity that it is from above</td>', 'Impressive photograph, but you should have tried to frame your model at an angle to improve a composition and reduce the ambiguity that it is from above', '2003-03-19 15:23:46.000000', NULL, 1),
(241539, 14386, 6913, '<td valign="top">I like this image as a photo for its black on black subtlety, but as a product shot it is probably not as strong - a contrasting background maybe? an extra light source? a coloured light?</td>', 'I like this image as a photo for its black on black subtlety, but as a product shot it is probably not as strong - a contrasting background maybe? an extra light source? a coloured light?', '2003-03-19 15:30:14.000000', NULL, 1),
(241570, 14864, 6643, '<td valign="top">Excellent angle!</td>', 'Excellent angle!', '2003-03-19 16:02:34.000000', NULL, 1),
(241572, 14743, 6451, '<td valign="top">Nice image.  I really like the range of colors used and the ripples in the water also look very nice in the image.  Good job.</td>', 'Nice image.  I really like the range of colors used and the ripples in the water also look very nice in the image.  Good job.', '2003-03-19 16:09:51.000000', NULL, 1),
(241573, 14922, 6451, '<td valign="top">Nice image.  Very good idea.  Where was this picture taken at??  I like the different range of color and texture. Good job.</td>', 'Nice image.  Very good idea.  Where was this picture taken at??  I like the different range of color and texture. Good job.', '2003-03-19 16:10:57.000000', NULL, 1),
(241574, 14697, 6451, '<td valign="top">Wasn''t the challenge from above?? This is taken from below.  Nice image though, but I think maybe more range of color needs to be displayed to give the photo any interest.</td>', 'Wasn''t the challenge from above?? This is taken from below.  Nice image though, but I think maybe more range of color needs to be displayed to give the photo any interest.', '2003-03-19 16:12:13.000000', NULL, 1),
(241575, 14790, 6870, '<td valign="top">Lines, focus, patterns: simply wonderful. My eyes find lots of interest in this "simple" image. 10 from me (one of 3 10s in my book).</td>', 'Lines, focus, patterns: simply wonderful. My eyes find lots of interest in this "simple" image. 10 from me (one of 3 10s in my book).', '2003-03-19 16:13:01.000000', NULL, 1),
(241576, 14945, 6451, '<td valign="top">What is this photo supposed to represent?? I''m a little bit confused.  Nice colors and focus.  Good job.</td>', 'What is this photo supposed to represent?? I''m a little bit confused.  Nice colors and focus.  Good job.', '2003-03-19 16:13:09.000000', NULL, 1),
(241577, 14886, 6451, '<td valign="top">I don''t understand how this meets the challenge, but it is a nice quality photo.</td>', 'I don''t understand how this meets the challenge, but it is a nice quality photo.', '2003-03-19 16:14:09.000000', NULL, 1),
(241579, 14814, 6870, '<td valign="top">There were a few shots of chairs and tables from above, but this, I feel, is the best. I love how the tiles are at a diagonal while the tables/chairs are horiz and vertical, and the roundness of the tables contrasts well with the other lines. This is simply a well composed image. I hope it does well.</td>', 'There were a few shots of chairs and tables from above, but this, I feel, is the best. I love how the tiles are at a diagonal while the tables/chairs are horiz and vertical, and the roundness of the tables contrasts well with the other lines. This is simply a well composed image. I hope it does well.', '2003-03-19 16:14:45.000000', NULL, 1),
(241580, 14802, 6451, '<td valign="top">Nice image.  Good use of shadows as well.  I like how the patterns on the floor and chair, as well as the angled placement of the chair makes for a very good image.  Nice job.</td>', 'Nice image.  Good use of shadows as well.  I like how the patterns on the floor and chair, as well as the angled placement of the chair makes for a very good image.  Nice job.', '2003-03-19 16:15:28.000000', NULL, 1),
(241581, 14763, 6870, '<td valign="top">Stunning and simple. Well composed and interesting. Colors are marvelous. I wish the oranges and whole teapot were as sharp as the teapot''s lid. Well done.</td>', 'Stunning and simple. Well composed and interesting. Colors are marvelous. I wish the oranges and whole teapot were as sharp as the teapot''s lid. Well done.', '2003-03-19 16:15:59.000000', NULL, 1),
(241582, 14840, 6451, '<td valign="top">Creative image.  Good photo quality.</td>', 'Creative image.  Good photo quality.', '2003-03-19 16:16:52.000000', NULL, 1),
(241583, 14417, 6451, '<td valign="top">Nice image and use of texture and pattern in your image. Good job.</td>', 'Nice image and use of texture and pattern in your image. Good job.', '2003-03-19 16:17:37.000000', NULL, 1),
(241585, 14133, 6451, '<td valign="top">Creative, but this angle isn''t taken from above.  The image also looks a little bit plain because there is no range of color or texture in the sky, and it doesn''t do much for the image.</td>', 'Creative, but this angle isn''t taken from above.  The image also looks a little bit plain because there is no range of color or texture in the sky, and it doesn''t do much for the image.', '2003-03-19 16:18:57.000000', NULL, 1),
(241586, 14771, 6451, '<td valign="top">Nice image and use of lines, colors, and textures.</td>', 'Nice image and use of lines, colors, and textures.', '2003-03-19 16:20:07.000000', NULL, 1),
(241587, 14812, 6451, '<td valign="top">I really like the range of color and patterns in the sky.  I also like the angle from which you chose to take the photo.  Good job.</td>', 'I really like the range of color and patterns in the sky.  I also like the angle from which you chose to take the photo.  Good job.', '2003-03-19 16:21:08.000000', NULL, 1),
(241588, 14668, 6451, '<td valign="top">Nice clear image.  I like the brightness in color and the lighting.  Good focus as well.</td>', 'Nice clear image.  I like the brightness in color and the lighting.  Good focus as well.', '2003-03-19 16:22:00.000000', NULL, 1),
(241589, 14846, 7033, '<td valign="top">Interesting shot... The reflection really adds to an otherwise boring scene.</td>', 'Interesting shot... The reflection really adds to an otherwise boring scene.', '2003-03-19 16:22:28.000000', NULL, 1),
(241590, 14699, 6451, '<td valign="top">Nice ideal, but the photo needs something more to give it range and value.</td>', 'Nice ideal, but the photo needs something more to give it range and value.', '2003-03-19 16:22:41.000000', NULL, 1),
(241591, 14907, 6097, '<td valign="top">Awesome shot!  Nice clarity and I love the colors.  I like the DOF used here.  Just the right amount of blur in the background but nice job keeping the subject in good focus throughout.  Good luck with the challenge!</td>', 'Awesome shot!  Nice clarity and I love the colors.  I like the DOF used here.  Just the right amount of blur in the background but nice job keeping the subject in good focus throughout.  Good luck with the challenge!', '2003-03-19 16:23:15.000000', NULL, 1),
(241592, 14282, 6451, '<td valign="top">Nice image and angle.  How did you take this ?? Good job.</td>', 'Nice image and angle.  How did you take this ?? Good job.', '2003-03-19 16:23:29.000000', NULL, 1),
(241593, 14875, 7033, '<td valign="top">Nice, vivid textures.  Might have benefited from a slightly larger DOF-- the closer parts seem to be on the verge of blurred</td>', 'Nice, vivid textures.  Might have benefited from a slightly larger DOF-- the closer parts seem to be on the verge of blurred', '2003-03-19 16:23:35.000000', NULL, 1),
(241595, 14816, 6451, '<td valign="top">Nice image.  Very clear and creative.  I really like the way that you took the picture so that the fence looked like it was winding.  Good job.</td>', 'Nice image.  Very clear and creative.  I really like the way that you took the picture so that the fence looked like it was winding.  Good job.', '2003-03-19 16:24:56.000000', NULL, 1),
(241596, 14849, 7033, '<td valign="top">Excellent contrast!  I wonder if the shot might not benefit from a bit tighter crop on the bottom of the frame, even though you would lose some of the roundness of the staircase.</td>', 'Excellent contrast!  I wonder if the shot might not benefit from a bit tighter crop on the bottom of the frame, even though you would lose some of the roundness of the staircase.', '2003-03-19 16:25:49.000000', NULL, 1),
(241597, 14384, 6451, '<td valign="top">Nice image.  Good use of colors and patterns.  I really like how you used the reflection of the bowl and light to creative the effect on the table.  Good job.</td>', 'Nice image.  Good use of colors and patterns.  I really like how you used the reflection of the bowl and light to creative the effect on the table.  Good job.', '2003-03-19 16:26:31.000000', NULL, 1),
(241599, 14914, 6451, '<td valign="top">Wow, very powerful image.  There is a lot of range in value and color as well as texture.  This provides for a great image and effect.  Good job.</td>', 'Wow, very powerful image.  There is a lot of range in value and color as well as texture.  This provides for a great image and effect.  Good job.', '2003-03-19 16:27:27.000000', NULL, 1),
(241600, 14851, 6451, '<td valign="top">Very cute image.  I think that the only thing I can spot is that it might have needed a little bit more focus.  But great photo!</td>', 'Very cute image.  I think that the only thing I can spot is that it might have needed a little bit more focus.  But great photo!', '2003-03-19 16:28:26.000000', NULL, 1),
(241601, 14773, 6451, '<td valign="top">Nice image and use of mirrors.  This is a really great idea and makes for a really good picture as well.</td>', 'Nice image and use of mirrors.  This is a really great idea and makes for a really good picture as well.', '2003-03-19 16:29:21.000000', NULL, 1),
(241602, 14876, 7033, '<td valign="top">Good shot; great leading lines!  I wonder if the shot might have benefited from a tighter crop, though...</td>', 'Good shot; great leading lines!  I wonder if the shot might have benefited from a tighter crop, though...', '2003-03-19 16:29:48.000000', NULL, 1),
(241603, 14917, 7033, '<td valign="top">Quite the view!  The reds (especially the cars) seem overly vivid to me-- maybe a bit out of balance.</td>', 'Quite the view!  The reds (especially the cars) seem overly vivid to me-- maybe a bit out of balance.', '2003-03-19 16:31:05.000000', NULL, 1),
(241605, 14920, 7033, '<td valign="top">Strong, vivid colors... but not a particularly interesting shot.</td>', 'Strong, vivid colors... but not a particularly interesting shot.', '2003-03-19 16:32:26.000000', NULL, 1),
(241608, 14873, 6451, '<td valign="top">Nice image. I like the leaves on the ground, they provide texture in the photo, as well as depth.  Good job.</td>', 'Nice image. I like the leaves on the ground, they provide texture in the photo, as well as depth.  Good job.', '2003-03-19 16:34:13.000000', NULL, 1),
(241609, 14808, 6451, '<td valign="top">Nice image.  I like the way the light hits the water making it look sort of irridescent.  Nice use of value and texture as well.  Good job.</td>', 'Nice image.  I like the way the light hits the water making it look sort of irridescent.  Nice use of value and texture as well.  Good job.', '2003-03-19 16:35:18.000000', NULL, 1),
(241610, 14752, 7033, '<td valign="top">Great shot!  I might have cropped it a bit tighter, though, to eliminate the overly bright area in the top right of the frame.  It kind of overwhelms the waterfall.</td>', 'Great shot!  I might have cropped it a bit tighter, though, to eliminate the overly bright area in the top right of the frame.  It kind of overwhelms the waterfall.', '2003-03-19 16:35:59.000000', NULL, 1),
(241611, 14931, 6451, '<td valign="top">Nice image and use of depth.  Where was this taken at?</td>', 'Nice image and use of depth.  Where was this taken at?', '2003-03-19 16:36:33.000000', NULL, 1),
(241612, 14723, 7033, '<td valign="top">Very strong lines-- I can almost hear the water hitting the bottom.  Well done!</td>', 'Very strong lines-- I can almost hear the water hitting the bottom.  Well done!', '2003-03-19 16:37:09.000000', NULL, 1),
(241614, 14780, 6451, '<td valign="top">Nice image and very creative idea.  This really does display the concept of "from above".  Good job.</td>', 'Nice image and very creative idea.  This really does display the concept of "from above".  Good job.', '2003-03-19 16:37:28.000000', NULL, 1),
(241615, 14819, 7033, '<td valign="top">Very nice night exposure.</td>', 'Very nice night exposure.', '2003-03-19 16:37:47.000000', NULL, 1),
(241616, 14708, 6451, '<td valign="top">Very nice image.  Good use of light and reflections.  Something seems to be a little bit distracting with having the objects in the corner of the photo, though.  Maybe if this photo was taken with a background of some sort and not just white underneath.</td>', 'Very nice image.  Good use of light and reflections.  Something seems to be a little bit distracting with having the objects in the corner of the photo, though.  Maybe if this photo was taken with a background of some sort and not just white underneath.', '2003-03-19 16:39:17.000000', NULL, 1),
(241617, 14015, 6451, '<td valign="top">Very nice image.  Good use of value in the patterns in the sky and on the ground.  This picture is very moving because of the different effects used.  Good job.</td>', 'Very nice image.  Good use of value in the patterns in the sky and on the ground.  This picture is very moving because of the different effects used.  Good job.', '2003-03-19 16:40:17.000000', NULL, 1),
