(241861, 14690, 7418, '<td valign="top">Great lighthouse.  Bad title.</td>', 'Great lighthouse.  Bad title.', '2003-03-19 22:07:36.000000', NULL, 1),
(241862, 14780, 6328, '<td valign="top">Really nice shot from the balcony of your Church.  Love those windows and the red carpet.  That pink window at the front with the Cross is beautiful.  You''ve done a really good job of capturing this on film</td>', 'Really nice shot from the balcony of your Church.  Love those windows and the red carpet.  That pink window at the front with the Cross is beautiful.  You''ve done a really good job of capturing this on film', '2003-03-19 22:07:54.000000', NULL, 1),
