(241889, 14708, 6325, '<td valign="top">Good composition.</td>', 'Good composition.', '2003-03-19 22:36:01.000000', NULL, 1),
(241895, 14397, 6325, '<td valign="top">Good composition. Maybe a little more range in the tones - somehting should be black. But very good.</td>', 'Good composition. Maybe a little more range in the tones - somehting should be black. But very good.', '2003-03-19 22:42:51.000000', NULL, 1),
(241896, 14750, 5792, '<td valign="top">I''m a romantic believer that you can fall in love with someone just from their picture.<br/> <br/>You have certainly achieved this for me with this beautifully composed image. The overexposure of the face multiplies the fair complexion of your subject. Nicely done.</td>', 'I''m a romantic believer that you can fall in love with someone just from their picture. You have certainly achieved this for me with this beautifully composed image. The overexposure of the face multiplies the fair complexion of your subject. Nicely done.', '2003-03-19 22:44:25.000000', NULL, 1),
(241898, 14312, 5792, '<td valign="top">Great action shot</td>', 'Great action shot', '2003-03-19 22:45:48.000000', NULL, 1),
(241899, 14718, 6325, '<td valign="top">I cannot decifer this photo. Sorry.</td>', 'I cannot decifer this photo. Sorry.', '2003-03-19 22:49:28.000000', NULL, 1),
(241901, 14677, 6325, '<td valign="top">Pretty nice. Color and reflection are well done. I would liked to have seen the composition more symmetric.</td>', 'Pretty nice. Color and reflection are well done. I would liked to have seen the composition more symmetric.', '2003-03-19 22:56:03.000000', NULL, 1),
(241902, 14850, 5792, '<td valign="top">Your subject looks like she is walking into the wind. If this isn''t a shot for an Icelandic tour guide I don''t know what is.<br/> <br/>Good color, focus and composition. The use of the flag is inspired.</td>', 'Your subject looks like she is walking into the wind. If this isn''t a shot for an Icelandic tour guide I don''t know what is. Good color, focus and composition. The use of the flag is inspired.', '2003-03-19 22:57:05.000000', NULL, 1),
(241903, 14015, 6325, '<td valign="top">Composition and lighting are good. I do not see how this meets the challenge.</td>', 'Composition and lighting are good. I do not see how this meets the challenge.', '2003-03-19 22:57:58.000000', NULL, 1),
(241905, 14942, 6325, '<td valign="top">Captures the challenge. Well composed. The motion and energy are refreshing. A little flat - more light and sharper focus. But very good.</td>', 'Captures the challenge. Well composed. The motion and energy are refreshing. A little flat - more light and sharper focus. But very good.', '2003-03-19 23:03:15.000000', NULL, 1),
(241907, 14938, 5792, '<td valign="top">I bet taking this shot was a "draining" experience.<br/> <br/>Good composition. Black and white whorks well in "this situation". Matches the challenge with more humor than any other.</td>', 'I bet taking this shot was a "draining" experience. Good composition. Black and white whorks well in "this situation". Matches the challenge with more humor than any other.', '2003-03-19 23:06:44.000000', NULL, 1),
(241909, 14795, 6325, '<td valign="top">Good shot. A haze filter might have cleaned up the distance.</td>', 'Good shot. A haze filter might have cleaned up the distance.', '2003-03-19 23:07:30.000000', NULL, 1),
(241911, 14832, 5792, '<td valign="top">I would have taken this without anyone in the frame to emphasize the beautiful lines in the frame.<br/> <br/>Very well done.</td>', 'I would have taken this without anyone in the frame to emphasize the beautiful lines in the frame. Very well done.', '2003-03-19 23:08:51.000000', NULL, 1),
