(241952, 14385, 5007, '<td valign="top">Nice composition and beautiful "weeds".</td>', 'Nice composition and beautiful "weeds".', '2003-03-19 23:51:16.000000', NULL, 1),
(241955, 14728, 5007, '<td valign="top">Very nice. I like the crystal appearance of the water.</td>', 'Very nice. I like the crystal appearance of the water.', '2003-03-19 23:56:27.000000', NULL, 1),
(241956, 14846, 5007, '<td valign="top">I love the reflection. Well done.</td>', 'I love the reflection. Well done.', '2003-03-20 00:00:23.000000', NULL, 1),
(241958, 14385, 5120, '<td valign="top">I love to take pictures like this one.  In fact this looks very similar to some I took over the weekend.  Overall I think you did a good job here.  It might have been better if you had clipped off the one closed bud in the background and went for a little less DOF.  The grass in the background is a tad distracting.</td>', 'I love to take pictures like this one.  In fact this looks very similar to some I took over the weekend.  Overall I think you did a good job here.  It might have been better if you had clipped off the one closed bud in the background and went for a little less DOF.  The grass in the background is a tad distracting.', '2003-03-20 00:03:53.000000', NULL, 1),
(241981, 14708, 2261, '<td valign="top">very nice, the dash of colour adds so much to this image. 9-Martin</td>', 'very nice, the dash of colour adds so much to this image. 9-Martin', '2003-03-20 04:55:32.000000', NULL, 1),
