(242369, 14603, 6328, '<td valign="top">Beauty of a photograph.  Colour of the mountains is outstanding.</td>', 'Beauty of a photograph.  Colour of the mountains is outstanding.', '2003-03-20 17:51:58.000000', NULL, 1),
(242370, 14759, 6328, '<td valign="top">Really great photo looking down at the steps, etc, great color and depth.</td>', 'Really great photo looking down at the steps, etc, great color and depth.', '2003-03-20 17:52:29.000000', NULL, 1),
(242371, 14635, 6328, '<td valign="top">Why are we looking up?  Aren''t we supposed to be looking down?</td>', 'Why are we looking up?  Aren''t we supposed to be looking down?', '2003-03-20 17:53:17.000000', NULL, 1),
(242372, 14768, 6328, '<td valign="top">Hey, nice cat!  Is he/she surprised to see you up there?</td>', 'Hey, nice cat!  Is he/she surprised to see you up there?', '2003-03-20 17:53:50.000000', NULL, 1),
(242373, 14949, 6328, '<td valign="top">Great shot from above.  Does he know you took it?</td>', 'Great shot from above.  Does he know you took it?', '2003-03-20 17:54:13.000000', NULL, 1),
(242374, 14423, 6328, '<td valign="top">Oh, oh!  Only 2 of them were obedient!  Lovely color, nice subjects, great idea.</td>', 'Oh, oh!  Only 2 of them were obedient!  Lovely color, nice subjects, great idea.', '2003-03-20 17:54:55.000000', NULL, 1),
(242375, 14894, 6328, '<td valign="top">Lots of depth here, good focus, lots of color and shade, lots of detail, good shot.</td>', 'Lots of depth here, good focus, lots of color and shade, lots of detail, good shot.', '2003-03-20 17:55:48.000000', NULL, 1),
(242376, 14681, 6328, '<td valign="top">Very lovely color, not much you can do to control the focus with fish moving around all the time, great idea and good photo.</td>', 'Very lovely color, not much you can do to control the focus with fish moving around all the time, great idea and good photo.', '2003-03-20 17:56:27.000000', NULL, 1),
(242377, 14771, 6328, '<td valign="top">Nice color, good lighting, good focus.</td>', 'Nice color, good lighting, good focus.', '2003-03-20 17:56:54.000000', NULL, 1),
(242378, 14857, 6328, '<td valign="top">Great reflections off the icy water, nice job of catching this photo.</td>', 'Great reflections off the icy water, nice job of catching this photo.', '2003-03-20 17:57:40.000000', NULL, 1),
(242380, 14950, 6328, '<td valign="top">That''s too bad.  Lovely colored flowers, nice photo, good dof, great lighting.</td>', 'That''s too bad.  Lovely colored flowers, nice photo, good dof, great lighting.', '2003-03-20 17:58:17.000000', NULL, 1),
(242381, 14443, 6328, '<td valign="top">Lovely detail here, good focus, great photo for the Challenge.</td>', 'Lovely detail here, good focus, great photo for the Challenge.', '2003-03-20 17:58:45.000000', NULL, 1),
(242383, 14762, 6328, '<td valign="top">I suppose it''s an okay photo.  Not that much of a wow to it.</td>', 'I suppose it''s an okay photo.  Not that much of a wow to it.', '2003-03-20 17:59:59.000000', NULL, 1),
(242384, 14751, 6376, '<td valign="top">A little off-center, but I like it ! ;-)</td>', 'A little off-center, but I like it ! ;-)', '2003-03-20 18:09:20.000000', NULL, 1),
(242385, 14838, 1439, '<td valign="top">love it nice use of DOF. 10:)</td>', 'love it nice use of DOF. 10:)', '2003-03-20 18:10:44.000000', NULL, 1),
(242392, 14848, 6376, '<td valign="top">He is SO CUTE !! Nice photograph... PERFECT  10 !!</td>', 'He is SO CUTE !! Nice photograph... PERFECT  10 !!', '2003-03-20 18:46:47.000000', NULL, 1),
(242393, 14883, 6376, '<td valign="top">Beautiful Colors !</td>', 'Beautiful Colors !', '2003-03-20 18:50:23.000000', NULL, 1),
