INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(242397, 14907, 6597, '<td valign="top">lots of color I like color</td>', 'lots of color I like color', '2003-03-20 19:02:11.000000', NULL, 1),
(242398, 14434, 6520, '<td valign="top">Great shot , my favorite of the challenge.You get the nod from me for the ribbon,the spiral staircase gives great lines,9!</td>', 'Great shot , my favorite of the challenge.You get the nod from me for the ribbon,the spiral staircase gives great lines,9!', '2003-03-20 19:05:50.000000', NULL, 1),
(242399, 14133, 6870, '<td valign="top">Okay, you''ve probably gotten lots of comments as to how this does not meet the challenge topic. Beyond that, you have found some interesting lines here, and you''ve used the contrast of the white sides and dark underbeams to emphasize these lines--ultimately, the eye ends up on these stair structures because that is the most interesting thing in the image. Somehow I don''t find that enough. Try coming here at a different time and see if different light would make it more interesting. Or try just cropping so that the image is filled with those cool stairs.</td>', 'Okay, you''ve probably gotten lots of comments as to how this does not meet the challenge topic. Beyond that, you have found some interesting lines here, and you''ve used the contrast of the white sides and dark underbeams to emphasize these lines--ultimately, the eye ends up on these stair structures because that is the most interesting thing in the image. Somehow I don''t find that enough. Try coming here at a different time and see if different light would make it more interesting. Or try just cropping so that the image is filled with those cool stairs.', '2003-03-20 19:12:49.000000', NULL, 1),
(242401, 14862, 6870, '<td valign="top">Gross. I don''t mind gross. I wish it were in focus, though. You could even crop in more so we could get a better look at it, as long as we still know it''s a hat. If you shot this close up, see if the macro feature on your camera works better at getting this in focus.</td>', 'Gross. I don''t mind gross. I wish it were in focus, though. You could even crop in more so we could get a better look at it, as long as we still know it''s a hat. If you shot this close up, see if the macro feature on your camera works better at getting this in focus.', '2003-03-20 19:14:51.000000', NULL, 1),
(242402, 14871, 6954, '<td valign="top">I think this would have great without the person in it. It distracts from an interesting subject.</td>', 'I think this would have great without the person in it. It distracts from an interesting subject.', '2003-03-20 19:20:12.000000', NULL, 1),
(242407, 14758, 2978, '<td valign="top">Nice macro but the background, IMO, it''s important too, is quite rough.</td>', 'Nice macro but the background, IMO, it''s important too, is quite rough.', '2003-03-20 20:24:27.000000', NULL, 1),
(242408, 14751, 2978, '<td valign="top">Great shot! I like the creativity and the technique is superb too. The only comment is that on the left is cropped out.</td>', 'Great shot! I like the creativity and the technique is superb too. The only comment is that on the left is cropped out.', '2003-03-20 20:31:44.000000', NULL, 1),
(242409, 14797, 2978, '<td valign="top">The problem is  the deer is blended into the background.</td>', 'The problem is  the deer is blended into the background.', '2003-03-20 20:32:52.000000', NULL, 1),
(242421, 14443, 6999, '<td valign="top">I''m marking this down because, whilst it clearly meets the challenge, and is possibly an interesting idea, I find it disorganised - too many textures, no one clear subject, no pattern to the image; and because of the lighting: the flash removes a lot of interest from the shot, leaves no impression of depth.</td>', 'I''m marking this down because, whilst it clearly meets the challenge, and is possibly an interesting idea, I find it disorganised - too many textures, no one clear subject, no pattern to the image; and because of the lighting: the flash removes a lot of interest from the shot, leaves no impression of depth.', '2003-03-20 20:54:35.000000', NULL, 1),
(242423, 14312, 2978, '<td valign="top">Great sport shot! The gradient colour is just perfect. Good luck</td>', 'Great sport shot! The gradient colour is just perfect. Good luck', '2003-03-20 20:55:35.000000', NULL, 1),
(242424, 14886, 5268, '<td valign="top">Absolutely beautifully posed shot. The low lighting around the model, contrasted with the smokey bright background, makes this photo awesome.  Great job!!  10.. Cub</td>', 'Absolutely beautifully posed shot. The low lighting around the model, contrasted with the smokey bright background, makes this photo awesome.  Great job!!  10.. Cub', '2003-03-20 20:55:54.000000', NULL, 1),
(242426, 14808, 2978, '<td valign="top">There is neithee subject to tell in the photo, IMO, nor the texture to make a pattern. So I don''t know what should I look at.</td>', 'There is neithee subject to tell in the photo, IMO, nor the texture to make a pattern. So I don''t know what should I look at.', '2003-03-20 20:57:47.000000', NULL, 1),
(242427, 14750, 5268, '<td valign="top">Beautiful photo! At first I thought the light on the right was too harsh but the more I look at it the more I think it makes the photo. The textures are great. Good job!! 8... Cub</td>', 'Beautiful photo! At first I thought the light on the right was too harsh but the more I look at it the more I think it makes the photo. The textures are great. Good job!! 8... Cub', '2003-03-20 20:58:06.000000', NULL, 1),
(242429, 14832, 2978, '<td valign="top">It''s a nice composition but people on the right should be more or cropped out completely.</td>', 'It''s a nice composition but people on the right should be more or cropped out completely.', '2003-03-20 20:59:18.000000', NULL, 1),
(242431, 14850, 5268, '<td valign="top">This is an excellent photo! I like the models focus and the way you created the pose. The flag colors are vivid with only a liltle bleeding from the lighting. At first the light appears harsh but upon close study it only enhances the photo. Great Shot!!! 9 ... Cub</td>', 'This is an excellent photo! I like the models focus and the way you created the pose. The flag colors are vivid with only a liltle bleeding from the lighting. At first the light appears harsh but upon close study it only enhances the photo. Great Shot!!! 9 ... Cub', '2003-03-20 20:59:59.000000', NULL, 1),
(242433, 14794, 5268, '<td valign="top">Good portrait with vivid colors and excellent focus. Composure is perfect and model''s essence is easily conveyed.  8... Cub</td>', 'Good portrait with vivid colors and excellent focus. Composure is perfect and model''s essence is easily conveyed.  8... Cub', '2003-03-20 21:02:19.000000', NULL, 1),
(242434, 14883, 2978, '<td valign="top">Strong contrast colours. Well done</td>', 'Strong contrast colours. Well done', '2003-03-20 21:03:48.000000', NULL, 1),
(242436, 14814, 6110, '<td valign="top">nice simple composition, good use of repeating &amp; contrasting shapes, like the lighting too.</td>', 'nice simple composition, good use of repeating & contrasting shapes, like the lighting too.', '2003-03-20 21:04:06.000000', NULL, 1),
(242441, 14763, 2978, '<td valign="top">Good use of contrast colours.</td>', 'Good use of contrast colours.', '2003-03-20 21:21:09.000000', NULL, 1),
(242443, 14686, 2978, '<td valign="top">Excellent abstract quality. I hope this goes well with the voters.</td>', 'Excellent abstract quality. I hope this goes well with the voters.', '2003-03-20 21:22:35.000000', NULL, 1),
(242444, 14886, 2978, '<td valign="top">Not sure how above is this.</td>', 'Not sure how above is this.', '2003-03-20 21:30:46.000000', NULL, 1),
(242445, 14434, 6886, '<td valign="top">Great shot.perfectly fits the theme.</td>', 'Great shot.perfectly fits the theme.', '2003-03-20 21:34:50.000000', NULL, 1),
(242447, 14798, 2978, '<td valign="top">Beautiful night landscape and related to the challenge.</td>', 'Beautiful night landscape and related to the challenge.', '2003-03-20 21:46:55.000000', NULL, 1),
(242450, 14880, 2978, '<td valign="top">Good macro and cropping. And the colour reflects the heat very well too. Well done.</td>', 'Good macro and cropping. And the colour reflects the heat very well too. Well done.', '2003-03-20 21:53:06.000000', NULL, 1),
(242451, 14704, 6328, '<td valign="top">Lovely colours, good focus , nice photograph</td>', 'Lovely colours, good focus , nice photograph', '2003-03-20 21:59:27.000000', NULL, 1),
(242453, 14588, 6328, '<td valign="top">Nice shot of a flag up on the flag pole, nice color of the sky too, but weren''t you supposed to shoot from UP on top of the flag pole looking DOWN at us?  I don''t think you''re going to get a pass on the Challenge rules. . .</td>', 'Nice shot of a flag up on the flag pole, nice color of the sky too, but weren''t you supposed to shoot from UP on top of the flag pole looking DOWN at us?  I don''t think you''re going to get a pass on the Challenge rules. . .', '2003-03-20 22:01:39.000000', NULL, 1),
(242454, 14873, 6328, '<td valign="top">That''s cute.  You''d better watch out for the dog that fits into this house.</td>', 'That''s cute.  You''d better watch out for the dog that fits into this house.', '2003-03-20 22:02:16.000000', NULL, 1),
(242455, 14678, 6328, '<td valign="top">Very original.  Good idea.</td>', 'Very original.  Good idea.', '2003-03-20 22:02:39.000000', NULL, 1),
(242456, 14716, 6328, '<td valign="top">Nice color, good focus.  Good idea for the challenge.</td>', 'Nice color, good focus.  Good idea for the challenge.', '2003-03-20 22:03:04.000000', NULL, 1),
(242457, 14591, 6328, '<td valign="top">Nice shot, good idea for the Challenge.</td>', 'Nice shot, good idea for the Challenge.', '2003-03-20 22:03:22.000000', NULL, 1),
(242458, 14816, 6328, '<td valign="top">Lovely black and white photo.  Love the shadows created by the Sun.</td>', 'Lovely black and white photo.  Love the shadows created by the Sun.', '2003-03-20 22:03:56.000000', NULL, 1),
(242459, 14694, 2978, '<td valign="top">The photo doesn''t tell anything to me. Lighting is too hard.</td>', 'The photo doesn''t tell anything to me. Lighting is too hard.', '2003-03-20 22:04:10.000000', NULL, 1),
(242460, 14725, 6328, '<td valign="top">Lovely colors of the candles, like the way you caught the flames of the candles, nice job.</td>', 'Lovely colors of the candles, like the way you caught the flames of the candles, nice job.', '2003-03-20 22:06:08.000000', NULL, 1),
(242462, 14152, 6328, '<td valign="top">lovely colors here, nice photograph, good lighting too. nice job.</td>', 'lovely colors here, nice photograph, good lighting too. nice job.', '2003-03-20 22:06:55.000000', NULL, 1),
(242463, 14910, 6328, '<td valign="top">Great idea for your looking up, er, looking down photo.  nice shadows and sunlight too.  Good colors.</td>', 'Great idea for your looking up, er, looking down photo.  nice shadows and sunlight too.  Good colors.', '2003-03-20 22:07:49.000000', NULL, 1),
(242464, 14668, 6328, '<td valign="top">Good colors on the flower and the greenery. Nice focus.</td>', 'Good colors on the flower and the greenery. Nice focus.', '2003-03-20 22:08:22.000000', NULL, 1),
(242465, 14757, 6328, '<td valign="top">That''s cute.  Lighting seems a bit bright, color looks fine.</td>', 'That''s cute.  Lighting seems a bit bright, color looks fine.', '2003-03-20 22:09:17.000000', NULL, 1),
(242466, 14623, 6328, '<td valign="top">Nice job, good idea, would have been great for the St Patrick''s photo Challenge.</td>', 'Nice job, good idea, would have been great for the St Patrick''s photo Challenge.', '2003-03-20 22:09:57.000000', NULL, 1),
(242467, 14819, 6328, '<td valign="top">Great shot of the Watefront in Vancouver.  Lovely color, great lighting.</td>', 'Great shot of the Watefront in Vancouver.  Lovely color, great lighting.', '2003-03-20 22:10:44.000000', NULL, 1),
(242471, 14015, 6328, '<td valign="top">Really nice portrait, great colors, great lighting, nice details, only problem: you\''re looking UP at her, and you\''re supposed to be taking the photo looking DOWN according to the rules of the challenge, so I\''m not sure if you\''re going to get a passing mark. . .</td>', 'Really nice portrait, great colors, great lighting, nice details, only problem: you\''re looking UP at her, and you\''re supposed to be taking the photo looking DOWN according to the rules of the challenge, so I\''m not sure if you\''re going to get a passing mark. . .', '2003-03-20 22:14:45.000000', NULL, 1),
(242472, 14909, 2978, '<td valign="top">Nice!! xcellent linghting colours and composition.</td>', 'Nice!! xcellent linghting colours and composition.', '2003-03-20 22:18:06.000000', NULL, 1),
(242475, 14907, 2978, '<td valign="top">Lovely! The backgroud contrast works well. only it the angle desn''t seem so from above.</td>', 'Lovely! The backgroud contrast works well. only it the angle desn''t seem so from above.', '2003-03-20 22:26:48.000000', NULL, 1),
(242477, 14628, 2978, '<td valign="top">Wow! One of the best shot of reflected from above so far. Good luck!</td>', 'Wow! One of the best shot of reflected from above so far. Good luck!', '2003-03-20 22:30:30.000000', NULL, 1),
