(243254, 14690, 3320, '<td valign="top">Nice shot. I do not like the explanations in the title. I do not like the red border it distract too much from the image. Nice angle and nice photo. Lionel</td>', 'Nice shot. I do not like the explanations in the title. I do not like the red border it distract too much from the image. Nice angle and nice photo. Lionel', '2003-03-22 21:32:59.000000', NULL, 1),
(243256, 14886, 3320, '<td valign="top">Nice tone contrast and nice colors. I like the foregoround/background opposition. altought I do not consider this as ''from above'' I would have score it higher in an appropriate challenge.</td>', 'Nice tone contrast and nice colors. I like the foregoround/background opposition. altought I do not consider this as ''from above'' I would have score it higher in an appropriate challenge.', '2003-03-22 21:39:05.000000', NULL, 1),
(243257, 14386, 3320, '<td valign="top">Very clean and sharp. A little too close to the top of the frame I would have made the space above and below the cam equal.</td>', 'Very clean and sharp. A little too close to the top of the frame I would have made the space above and below the cam equal.', '2003-03-22 21:40:34.000000', NULL, 1),
(243259, 14775, 3320, '<td valign="top">Very soft and nice ... I like that you did not ''sharpen'' or contrast. I like the ''hand only/no nails'' approach. Very nice composition. One of my prefered this week. 9. Lionel</td>', 'Very soft and nice ... I like that you did not ''sharpen'' or contrast. I like the ''hand only/no nails'' approach. Very nice composition. One of my prefered this week. 9. Lionel', '2003-03-22 21:47:37.000000', NULL, 1),
