INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(243289, 14723, 6325, '<td valign="top">"Over filling a flower vase"? Nice shot. The angle works - so many do not. Like the colors.</td>', '"Over filling a flower vase"? Nice shot. The angle works - so many do not. Like the colors.', '2003-03-22 22:48:53.000000', NULL, 1),
(243291, 14904, 6325, '<td valign="top">Very good. Nice tonal range. Good stop action. Looks like you did it in just one take! I little soft in the focus.</td>', 'Very good. Nice tonal range. Good stop action. Looks like you did it in just one take! I little soft in the focus.', '2003-03-22 22:51:45.000000', NULL, 1),
(243292, 14931, 6325, '<td valign="top">Good night shot. Very clear and well focused and exposed.  Clearly from above.</td>', 'Good night shot. Very clear and well focused and exposed.  Clearly from above.', '2003-03-22 22:54:26.000000', NULL, 1),
(243294, 14822, 6325, '<td valign="top">The exposure and focus are good. The composition is too busy to hold my interest. Maybe loose the top part with the windows showing the taxi line.</td>', 'The exposure and focus are good. The composition is too busy to hold my interest. Maybe loose the top part with the windows showing the taxi line.', '2003-03-22 22:56:31.000000', NULL, 1),
(243296, 14860, 6325, '<td valign="top">Nice colors. Background would have been better out of focus while the flower could be in better focus - smaller f# if your camera can be set for aperture priority.</td>', 'Nice colors. Background would have been better out of focus while the flower could be in better focus - smaller f# if your camera can be set for aperture priority.', '2003-03-22 22:58:29.000000', NULL, 1),
(243297, 14716, 6325, '<td valign="top">Everything is too much the same color and tone. Hard to see. Maybe get in closer and more from above to get the head.</td>', 'Everything is too much the same color and tone. Hard to see. Maybe get in closer and more from above to get the head.', '2003-03-22 23:00:22.000000', NULL, 1),
(243300, 14798, 6325, '<td valign="top">Nice sky and fog. Exposure looks OK. The lights are too blurry for me.</td>', 'Nice sky and fog. Exposure looks OK. The lights are too blurry for me.', '2003-03-22 23:02:12.000000', NULL, 1),
(243301, 14876, 6325, '<td valign="top">WOW. Where did you find this? Le tme guess, your are writing your novel on this? I think very sharp focus and snappy lighting with stronger reflections from the keys would have helped.</td>', 'WOW. Where did you find this? Le tme guess, your are writing your novel on this? I think very sharp focus and snappy lighting with stronger reflections from the keys would have helped.', '2003-03-22 23:05:49.000000', NULL, 1),
(243302, 14883, 6325, '<td valign="top">These super saturated colors and high contrast work well for this image.</td>', 'These super saturated colors and high contrast work well for this image.', '2003-03-22 23:08:54.000000', NULL, 1),
(243303, 14937, 6325, '<td valign="top">More focus near the center would have made this better for me.</td>', 'More focus near the center would have made this better for me.', '2003-03-22 23:15:10.000000', NULL, 1),
(243304, 14620, 6325, '<td valign="top">Nice gold colors. I find the image a little confusing.</td>', 'Nice gold colors. I find the image a little confusing.', '2003-03-22 23:23:37.000000', NULL, 1),
