(243632, 14650, 2605, '<td valign="top">well done ... I like the contrast of the parked cars, I like how you can almost divide the photo down the middle for two completely different shots. definitely one of the best night shots in this challenge.</td>', 'well done ... I like the contrast of the parked cars, I like how you can almost divide the photo down the middle for two completely different shots. definitely one of the best night shots in this challenge.', '2003-03-23 17:50:58.000000', NULL, 1),
(243633, 14751, 2605, '<td valign="top">wow, beautiful colors.</td>', 'wow, beautiful colors.', '2003-03-23 17:51:29.000000', NULL, 1),
(243635, 14936, 2605, '<td valign="top">ahh, I love seattle. this is lovely.</td>', 'ahh, I love seattle. this is lovely.', '2003-03-23 17:53:05.000000', NULL, 1),
(243636, 14434, 3320, '<td valign="top">Great shot ! I understand the ''corridor'' thing but I would have personnaly prefer ''just the stairs''. One of my prefered this week. 8. Lionel</td>', 'Great shot ! I understand the ''corridor'' thing but I would have personnaly prefer ''just the stairs''. One of my prefered this week. 8. Lionel', '2003-03-23 17:53:47.000000', NULL, 1),
(243637, 14690, 2605, '<td valign="top">wow, very intense shot. the title adds quite a bit of mystery/danger. the lighthouse looks so tiny! the scale seems to be skewed, I can''t wrap my head around the true distance.</td>', 'wow, very intense shot. the title adds quite a bit of mystery/danger. the lighthouse looks so tiny! the scale seems to be skewed, I can''t wrap my head around the true distance.', '2003-03-23 17:54:31.000000', NULL, 1),
(243639, 14243, 2605, '<td valign="top">cute! excellent expressions.</td>', 'cute! excellent expressions.', '2003-03-23 17:55:01.000000', NULL, 1),
(243640, 14689, 2978, '<td valign="top">This is great. I''m not sure wether it''s taken from above or not but still a good shot.</td>', 'This is great. I''m not sure wether it''s taken from above or not but still a good shot.', '2003-03-23 17:55:20.000000', NULL, 1),
(243641, 14846, 3320, '<td valign="top">Grezat shot and colors. I like a lot the reflections and the fishes over the building. One of my prefered shot this week. I like the symmetry in the ''chaos'' ( diagonal line).</td>', 'Grezat shot and colors. I like a lot the reflections and the fishes over the building. One of my prefered shot this week. I like the symmetry in the ''chaos'' ( diagonal line).', '2003-03-23 17:55:46.000000', NULL, 1),
(243642, 14038, 2605, '<td valign="top">kind of creepy title ... a little stalker-ish</td>', 'kind of creepy title ... a little stalker-ish', '2003-03-23 17:56:03.000000', NULL, 1),
(243643, 14909, 2605, '<td valign="top">great colors in the border.</td>', 'great colors in the border.', '2003-03-23 17:57:14.000000', NULL, 1),
(243644, 14894, 3320, '<td valign="top">I like the shot a lot, the perspective, the person and the dog , the movment with them. I am very distracted by the heavy blue cast of the shadow and I think you should reduce it. Very nice picture anyway. 8. Lionel</td>', 'I like the shot a lot, the perspective, the person and the dog , the movment with them. I am very distracted by the heavy blue cast of the shadow and I think you should reduce it. Very nice picture anyway. 8. Lionel', '2003-03-23 17:57:17.000000', NULL, 1),
(243645, 14518, 2605, '<td valign="top">excellent frame</td>', 'excellent frame', '2003-03-23 18:00:34.000000', NULL, 1),
(243646, 14434, 3102, '<td valign="top">Very interesting shot -- great work!  Is that a person lying on the floor at the bottom?  I''ll be curious to read your comments after the contest is over.  I''m betting this will be a contender this week!</td>', 'Very interesting shot -- great work!  Is that a person lying on the floor at the bottom?  I''ll be curious to read your comments after the contest is over.  I''m betting this will be a contender this week!', '2003-03-23 18:03:01.000000', NULL, 1),
(243647, 14747, 3102, '<td valign="top">It''s unfortunate that a lot of "cute kid" pictures don''t do well here.  This is a "cute kid," and it will do well by me!  Great vantage point and expression on her face.  Nicely done!</td>', 'It''s unfortunate that a lot of "cute kid" pictures don''t do well here.  This is a "cute kid," and it will do well by me!  Great vantage point and expression on her face.  Nicely done!', '2003-03-23 18:04:02.000000', NULL, 1),
(243648, 14850, 3102, '<td valign="top">Great shot of a beautiful girl!  It''s an interesting expression -- I don''t know quite what she''s trying to say with that look :)</td>', 'Great shot of a beautiful girl!  It''s an interesting expression -- I don''t know quite what she''s trying to say with that look :)', '2003-03-23 18:05:01.000000', NULL, 1),
(243649, 14685, 3102, '<td valign="top">Great shot -- almost does indeed take the viewer back to days gone by!  I like how you caught the guy with the bike in the shot -- it really reinforces the whole theme of the photo.</td>', 'Great shot -- almost does indeed take the viewer back to days gone by!  I like how you caught the guy with the bike in the shot -- it really reinforces the whole theme of the photo.', '2003-03-23 18:06:07.000000', NULL, 1),
(243650, 14006, 2605, '<td valign="top">great contrast</td>', 'great contrast', '2003-03-23 18:06:20.000000', NULL, 1),
(243651, 14693, 3102, '<td valign="top">Playground shots seem to never do well here -- but I hope this is an exception!  This is an interesting vantage point, and a very well done shot.</td>', 'Playground shots seem to never do well here -- but I hope this is an exception!  This is an interesting vantage point, and a very well done shot.', '2003-03-23 18:06:56.000000', NULL, 1),
(243652, 14798, 3102, '<td valign="top">Very nice!  I might have zoomed in just a teeny bit to try to capture a little more detail on some of the buildings, like the ones visible in the bottom mid-right.  Still a great job with a magical feel to it.</td>', 'Very nice!  I might have zoomed in just a teeny bit to try to capture a little more detail on some of the buildings, like the ones visible in the bottom mid-right.  Still a great job with a magical feel to it.', '2003-03-23 18:08:29.000000', NULL, 1),
(243653, 14814, 3102, '<td valign="top">A great, simple shot!  I might have preferred it without the shadows, but I still enjoy it for the repeating patterns and subtle colors.  Well done!</td>', 'A great, simple shot!  I might have preferred it without the shadows, but I still enjoy it for the repeating patterns and subtle colors.  Well done!', '2003-03-23 18:09:29.000000', NULL, 1),
(243656, 14886, 3102, '<td valign="top">Nice shot -- very nice girl!  I like the way you exposed this one with the well exposed girl (I mean "photographically well-exposed"), and the bright dock in the background.  Interesting, and well-done!</td>', 'Nice shot -- very nice girl!  I like the way you exposed this one with the well exposed girl (I mean "photographically well-exposed"), and the bright dock in the background.  Interesting, and well-done!', '2003-03-23 18:11:07.000000', NULL, 1),
(243657, 14750, 3102, '<td valign="top">Nicely done -- I like the vivid colors.</td>', 'Nicely done -- I like the vivid colors.', '2003-03-23 18:11:46.000000', NULL, 1),
(243658, 14942, 3102, '<td valign="top">Great vantage point!  It''s the kind of shot you can explore for quite a while since there''s so much to see.  It''s done in such a way that there''s a lot going on, but the shot is not at all "busy."  Well done.</td>', 'Great vantage point!  It''s the kind of shot you can explore for quite a while since there''s so much to see.  It''s done in such a way that there''s a lot going on, but the shot is not at all "busy."  Well done.', '2003-03-23 18:12:44.000000', NULL, 1),
(243659, 14243, 3102, '<td valign="top">What a fun shot!  The expressions on the kids'' faces are great!  The colors are great, and it''s an all-around wonderful shot.</td>', 'What a fun shot!  The expressions on the kids'' faces are great!  The colors are great, and it''s an all-around wonderful shot.', '2003-03-23 18:13:49.000000', NULL, 1),
(243660, 14840, 3102, '<td valign="top">Well, in one sense its a little gross, but it''s still a great shot.  I''m sure some folks are finding it repulsive, but I like it.  The toning is great, and it "tells a story."  Or at least we can make up our own story :)</td>', 'Well, in one sense its a little gross, but it''s still a great shot.  I''m sure some folks are finding it repulsive, but I like it.  The toning is great, and it "tells a story."  Or at least we can make up our own story :)', '2003-03-23 18:16:00.000000', NULL, 1),
(243663, 14620, 3102, '<td valign="top">A great vantage point and an interesting subject!  Something seems just a teeny bit off somewhere, though.  It looks like it was blurred and sharpened, or something like that.  There''s something here that gives the shot a little bit of an odd effect, but I can''t quite pinpoint it.  It''s just a very subtle distraction... but an overall nice shot. - 8</td>', 'A great vantage point and an interesting subject!  Something seems just a teeny bit off somewhere, though.  It looks like it was blurred and sharpened, or something like that.  There''s something here that gives the shot a little bit of an odd effect, but I can''t quite pinpoint it.  It''s just a very subtle distraction... but an overall nice shot. - 8', '2003-03-23 18:18:19.000000', NULL, 1),
(243664, 14298, 3102, '<td valign="top">It took me quite a while to realize what I was looking at here.  The fish blends in quite a bit with the surroundings.</td>', 'It took me quite a while to realize what I was looking at here.  The fish blends in quite a bit with the surroundings.', '2003-03-23 18:19:54.000000', NULL, 1),
(243665, 14659, 3102, '<td valign="top">If the child''s face had been exposed better, this would have been a great shot!</td>', 'If the child''s face had been exposed better, this would have been a great shot!', '2003-03-23 18:20:53.000000', NULL, 1),
(243666, 14944, 3102, '<td valign="top">I would have been tempted to pan a bit to the right to make the pyramid a bit more of a focal point, but I still enjoy this one.</td>', 'I would have been tempted to pan a bit to the right to make the pyramid a bit more of a focal point, but I still enjoy this one.', '2003-03-23 18:22:08.000000', NULL, 1),
(243667, 14907, 3102, '<td valign="top">Excellent macro work!  At least I certainly HOPE this is a macro... :)</td>', 'Excellent macro work!  At least I certainly HOPE this is a macro... :)', '2003-03-23 18:22:53.000000', NULL, 1),
(243668, 14793, 3102, '<td valign="top">A great shot -- nice tinting, too.  This would make a good stock photo as well.</td>', 'A great shot -- nice tinting, too.  This would make a good stock photo as well.', '2003-03-23 18:26:01.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(243669, 14265, 3102, '<td valign="top">I like the colors of the water -- it almost looks like a summer shot!  Overall the image could be just a little sharper, but it''s certainly a great vantage point and an overall nice photo.  My only other comment is that it may have helped the composition just a little bit to move the largest building slightly off-center. - 8</td>', 'I like the colors of the water -- it almost looks like a summer shot!  Overall the image could be just a little sharper, but it''s certainly a great vantage point and an overall nice photo.  My only other comment is that it may have helped the composition just a little bit to move the largest building slightly off-center. - 8', '2003-03-23 18:27:50.000000', NULL, 1),
(243680, 14904, 3306, '<td valign="top">Very nice. My favorite of the week. Definitely a winner!</td>', 'Very nice. My favorite of the week. Definitely a winner!', '2003-03-23 19:21:56.000000', NULL, 1),
(243681, 14790, 2978, '<td valign="top">Nice composition. IMO, in the deep is a bit too dark</td>', 'Nice composition. IMO, in the deep is a bit too dark', '2003-03-23 19:24:45.000000', NULL, 1),
(243682, 14711, 3306, '<td valign="top">There will probably be many people who will see this and not figure out that it was taken from above. This is a very intelligent shot. You will not get the credit it deserves.  Keep up the good work. Baltimore Rules.</td>', 'There will probably be many people who will see this and not figure out that it was taken from above. This is a very intelligent shot. You will not get the credit it deserves.  Keep up the good work. Baltimore Rules.', '2003-03-23 19:24:54.000000', NULL, 1),
